style.css:
@-moz-document domain("reddit.com") {
/* 01 / Reddit native theme tokens — required for inherited theme and shadow-root colors */
  :root,
  html.theme-beta,
  html.theme-rpl,
  html.theme-dark,
  html.theme-light,
  html body,
  html body .theme-beta,
  html body .theme-rpl,
  html body shreddit-app,
  html body shreddit-header {
      --color-neutral-background: #010501 !important;
      --color-neutral-background-weak: #07180b !important;
      --color-neutral-background-strong: #0c2412 !important;
      --color-neutral-background-hover: #0d2a17 !important;
      --color-neutral-background-selected: #12371e !important;
      --color-secondary-background: #07180b !important;
      --color-secondary-background-hover: #0d2a17 !important;
      --color-secondary-background-selected: #12371e !important;
      --color-neutral-content: #a5ffb7 !important;
      --color-neutral-content-weak: #77ba8c !important;
      --color-neutral-content-strong: #b6ffc5 !important;
      --color-neutral-border: rgba(0, 255, 102, 0.27) !important;
      --color-primary: #00ff66 !important;
      --color-primary-onBackground: #00ff66 !important;
      --color-primary-background: #00c851 !important;
      --color-primary-background-hover: #00ff66 !important;
      --color-button-secondary-background: #0c2412 !important;
      --color-button-primary-background: #00c851 !important;
      --color-button-primary-text: #010501 !important;
  }

    /* 02 / Global page backgrounds */
  html,
  html body,
  html body shreddit-app,
  html body #main-content,
  html body main,
  html body shreddit-feed,
  html body .bg-neutral-background {
      background-color: #010501 !important;
      color: #a5ffb7 !important;
      color-scheme: dark !important;
  }

    /* 03 / Panels, sidebars, and dialogs */
  html body shreddit-header,
  html body reddit-header-large,
  html body #left-sidebar-container,
  html body #right-sidebar-container,
  html body .left-sidebar-container,
  html body .right-sidebar-container,
  html body reddit-sidebar-nav,
  html body .bg-neutral-background-weak,
  html body .bg-neutral-background-strong,
  html body .bg-secondary-background,
  html body aside,
  html body [role="dialog"],
  html body [role="menu"],
  html body faceplate-dialog,
  html body faceplate-dropdown-menu {
      background-color: #07180b !important;
      border-color: rgba(0, 255, 102, 0.25) !important;
  }

    /* 04 / Terminal typography */
  html body div,
  html body span,
  html body p,
  html body a,
  html body h1,
  html body h2,
  html body h3,
  html body h4,
  html body h5,
  html body h6,
  html body small,
  html body strong,
  html body em,
  html body b,
  html body i,
  html body label,
  html body li,
  html body time,
  html body article,
  html body section,
  html body button,
  html body input,
  html body textarea,
  html body select,
  html body figcaption,
  html body summary,
  html body blockquote,
  html body [role="tab"],
  html body [role="button"],
  html body [role="menuitem"],
  html body [contenteditable="true"] {
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
      color: #a5ffb7 !important;
      letter-spacing: .3px !important;
      text-shadow: 0 0 4px rgba(0, 255, 102, 0.24) !important;
  }

    /* 05 / Headings and post titles */
  html body h1,
  html body h2,
  html body h3,
  html body h4,
  html body h5,
  html body h6,
  html body h1 span,
  html body h1 a,
  html body h1 strong,
  html body h2 span,
  html body h2 a,
  html body h2 strong,
  html body h3 span,
  html body h3 a,
  html body h3 strong,
  html body h4 span,
  html body h4 a,
  html body h4 strong,
  html body h5 span,
  html body h5 a,
  html body h5 strong,
  html body h6 span,
  html body h6 a,
  html body h6 strong,
  html body shreddit-post [slot="title"],
  html body shreddit-post a[id^="post-title"],
  html body shreddit-post h1[id^="post-title"],
  html body shreddit-post h2[id^="post-title"],
  html body shreddit-post h3[id^="post-title"],
  html body shreddit-post [data-testid="post-title"] {
      color: #00ff66 !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
      font-weight: 700 !important;
      letter-spacing: .45px !important;
      text-shadow: 0 0 5px rgba(0, 255, 102, 0.72),
          0 0 13px rgba(0, 255, 102, 0.32),
          0 0 23px rgba(0, 255, 102, 0.10) !important;
  }

    /* 06 / Hyperlinks */
  html body a,
  html body a:visited,
  html body a span,
  html body a strong,
  html body a p {
      color: #00ff66 !important;
      text-decoration-color: rgba(0, 255, 102, 0.48) !important;
      text-shadow: 0 0 5px rgba(0, 255, 102, 0.36) !important;
  }

  html body a:hover,
  html body a:hover span,
  html body a:hover strong,
  html body a:hover p {
      color: #b6ffc5 !important;
      text-decoration-color: #00ff66 !important;
      text-shadow: 0 0 7px rgba(0, 255, 102, 0.80),
          0 0 16px rgba(0, 255, 102, 0.35) !important;
  }

    /* 07 / Utility text colors */
  html body [class~="text-white"],
  html body [class~="text-black"],
  html body [class^="text-gray-"],
  html body [class*=" text-gray-"],
  html body [class^="text-neutral-"],
  html body [class*=" text-neutral-"],
  html body [class^="text-blue-"],
  html body [class*=" text-blue-"],
  html body [class^="text-slate-"],
  html body [class*=" text-slate-"],
  html body .text-neutral-content,
  html body .text-neutral-content-weak {
      color: #a5ffb7 !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  }

    /* 08 / Post cards */
  html body shreddit-post,
  html body [data-testid="post-container"] {
      background-color: #07180b !important;
      border: 1px solid rgba(0, 255, 102, 0.27) !important;
      border-radius: 8px !important;
      transition: border-color .2s ease, box-shadow .2s ease !important;
  }

  html body shreddit-post:hover,
  html body [data-testid="post-container"]:hover {
      border-color: rgba(0, 255, 102, 0.65) !important;
      box-shadow: 0 0 10px rgba(0, 255, 102, 0.19),
          0 0 22px rgba(0, 255, 102, 0.07) !important;
  }

    /* 09 / Post bodies and comments */
  html body shreddit-post [slot="text-body"],
  html body shreddit-post [data-testid="post-text-container"],
  html body shreddit-post .md,
  html body shreddit-post .usertext-body,
  html body shreddit-post shreddit-post-text-body,
  html body shreddit-post [id$="-post-rtjson-content"],
  html body shreddit-post [id$="-comment-rtjson-content"],
  html body shreddit-comment [slot="text-body"],
  html body shreddit-comment [data-testid="post-text-container"],
  html body shreddit-comment .md,
  html body shreddit-comment .usertext-body,
  html body shreddit-comment shreddit-post-text-body,
  html body shreddit-comment [id$="-post-rtjson-content"],
  html body shreddit-comment [id$="-comment-rtjson-content"] {
      color: #a5ffb7 !important;
      line-height: 1.6 !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  }

  html body shreddit-comment,
  html body shreddit-comment-tree,
  html body #comment-tree {
      color: #a5ffb7 !important;
      border-color: rgba(0, 255, 102, 0.27) !important;
  }

  html body shreddit-post blockquote,
  html body shreddit-comment blockquote {
      border-left: 3px solid #00ff66 !important;
      padding-left: 12px !important;
      color: #77ba8c !important;
  }

    /* 10 / Authors and metadata */
  html body [slot="credit-bar"],
  html body [data-testid="credit-bar"],
  html body [data-testid="post-meta"],
  html body [data-testid="comment-meta"],
  html body [data-testid="subreddit-name"],
  html body [class*="metadata"],
  html body [class*="timestamp"],
  html body [class*="secondary-text"],
  html body time {
      color: #77ba8c !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
      text-shadow: 0 0 3px rgba(0, 255, 102, 0.15) !important;
  }

  html body [slot="credit-bar"] a,
  html body [data-testid="credit-bar"] a {
      color: #b6ffc5 !important;
  }

    /* 11 / Header and sidebar navigation */
  html body shreddit-header,
  html body reddit-header-large,
  html body #left-sidebar-container,
  html body #right-sidebar-container,
  html body [data-testid="left-sidebar"],
  html body [data-testid="right-sidebar"] {
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
      border-color: rgba(0, 255, 102, 0.27) !important;
  }

  html body #left-sidebar-container a:hover,
  html body #right-sidebar-container a:hover,
  html body reddit-sidebar-nav a:hover,
  html body nav a:hover,
  html body aside a:hover {
      color: #b6ffc5 !important;
      background-color: #0c2412 !important;
      border-radius: 5px !important;
  }

    /* 12 / Tabs and active navigation */
  html body [role="tab"],
  html body [role="menuitem"],
  html body [aria-current="page"] {
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  }

  html body [role="tab"][aria-selected="true"],
  html body [aria-current="page"],
  html body [aria-selected="true"] {
      color: #00ff66 !important;
      border-color: #00ff66 !important;
      text-shadow: 0 0 7px rgba(0, 255, 102, 0.54) !important;
  }

    /* 13 / Buttons and voting controls */
  html body button,
  html body [role="button"],
  html body faceplate-button {
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
      letter-spacing: .35px !important;
      border-color: rgba(0, 255, 102, 0.27) !important;
  }

  html body button:hover,
  html body [role="button"]:hover,
  html body faceplate-button:hover {
      box-shadow: 0 0 9px rgba(0, 255, 102, 0.28) !important;
  }

  html body button[type="submit"],
  html body button[class*="button-primary"],
  html body faceplate-button[appearance="primary"],
  html body [data-testid="post-submit-button"] {
      background-color: #00c851 !important;
      color: #010501 !important;
      border-color: #00ff66 !important;
      text-shadow: none !important;
  }

  html body button[type="submit"] span,
  html body button[type="submit"] strong,
  html body button[type="submit"] div,
  html body button[class*="button-primary"] span,
  html body button[class*="button-primary"] strong,
  html body button[class*="button-primary"] div,
  html body faceplate-button[appearance="primary"] span,
  html body faceplate-button[appearance="primary"] strong,
  html body faceplate-button[appearance="primary"] div,
  html body [data-testid="post-submit-button"] span,
  html body [data-testid="post-submit-button"] strong,
  html body [data-testid="post-submit-button"] div {
      color: #010501 !important;
      text-shadow: none !important;
  }

  html body shreddit-post-vote-button,
  html body [data-testid="vote-arrows"],
  html body [data-post-click-location="vote"],
  html body shreddit-comment-action-row,
  html body shreddit-post-action-row {
      color: #b6ffc5 !important;
      border-color: rgba(0, 255, 102, 0.27) !important;
  }

  html body button[aria-pressed="true"] {
      color: #00ff66 !important;
      text-shadow: 0 0 8px rgba(0, 255, 102, 0.65) !important;
  }

    /* 14 / Search inputs and editors */
  html body input[type="text"],
  html body input[type="search"],
  html body input:not([type]),
  html body textarea,
  html body select,
  html body [role="searchbox"],
  html body [role="textbox"],
  html body [contenteditable="true"] {
      background-color: #07180b !important;
      color: #b6ffc5 !important;
      caret-color: #00ff66 !important;
      border-color: rgba(0, 255, 102, 0.42) !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  }

  html body input::placeholder,
  html body textarea::placeholder {
      color: #77ba8c !important;
      opacity: 1 !important;
  }

  html body input[type="text"]:focus,
  html body input[type="search"]:focus,
  html body textarea:focus,
  html body select:focus,
  html body [role="searchbox"]:focus,
  html body [role="textbox"]:focus,
  html body [contenteditable="true"]:focus {
      outline-color: #00ff66 !important;
      box-shadow: 0 0 9px rgba(0, 255, 102, 0.30) !important;
  }

    /* 15 / Flair, menus, separators */
  html body [data-testid*="flair"],
  html body [class*="flair"] {
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
      border-color: rgba(0, 255, 102, 0.27) !important;
  }

  html body [role="menu"],
  html body [role="listbox"],
  html body [role="tooltip"],
  html body [data-radix-popper-content-wrapper],
  html body faceplate-dialog {
      background-color: #07180b !important;
      border-color: rgba(0, 255, 102, 0.27) !important;
      color: #a5ffb7 !important;
  }

  html body hr,
  html body [role="separator"] {
      border-color: rgba(0, 255, 102, 0.27) !important;
  }

    /* 16 / Code blocks */
  html body pre,
  html body code,
  html body kbd,
  html body samp {
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
      color: #b6ffc5 !important;
      background-color: #0c2412 !important;
      border-color: rgba(0, 255, 102, 0.27) !important;
      text-shadow: none !important;
  }

  html body pre code {
      background-color: transparent !important;
  }

    /* 17 / Scrollbars and text selection */
  html {
      scrollbar-color: #176c35 #010501;
  }

  html body ::selection {
      background-color: #00c851 !important;
      color: #010501 !important;
      text-shadow: none !important;
  }

    /* 18 / Native image and video colors */
  html body img,
  html body video,
  html body canvas,
  html body picture {
      filter: none !important;
      mix-blend-mode: normal !important;
  }

    /* 19 / Reduced motion */
  @media (prefers-reduced-motion: reduce) {
    html body a,
    html body button,
    html body shreddit-post,
    html body [role="button"] {
        transition: none !important;
    }
  }

    /* 20 / Communities: native wrapper tokens and backgrounds */
  html body #left-sidebar,
  html body #left-sidebar-container,
  html body #flex-left-nav-container,
  html body nav[aria-label="Primary"] {
      --color-neutral-background: #07180b !important;
      --color-neutral-background-weak: #07180b !important;
      --color-neutral-background-hover: #0d2a17 !important;
      --color-neutral-background-selected: #12371e !important;
      --color-neutral-content: #a5ffb7 !important;
      --color-neutral-content-weak: #77ba8c !important;
      --color-neutral-content-strong: #b6ffc5 !important;
      --color-neutral-border: rgba(0, 255, 102, 0.27) !important;
      background-color: #07180b !important;
      color: #a5ffb7 !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  }

    /* 21 / Communities: list and expandable sidebar */
  html body #left-sidebar faceplate-expandable-section-helper,
  html body #left-sidebar faceplate-expandable-section-helper > details,
  html body #communities_section {
      --color-neutral-background: #07180b !important;
      --color-neutral-background-weak: #07180b !important;
      --color-neutral-content: #a5ffb7 !important;
      --color-neutral-content-weak: #77ba8c !important;
      background-color: #07180b !important;
      border-color: rgba(0, 255, 102, 0.27) !important;
      color: #a5ffb7 !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  }

    /* 22 / Communities: heading and disclosure icon */
  html body summary[aria-controls="communities_section"],
  html body summary[aria-controls="communities_section"] span,
  html body summary[aria-controls="communities_section"] strong,
  html body summary[aria-controls="communities_section"] div,
  html body summary[aria-controls="communities_section"] svg,
  html body summary[aria-controls="communities_section"] faceplate-icon {
      color: #00ff66 !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
      font-weight: 700 !important;
      letter-spacing: .45px !important;
      text-shadow: 0 0 6px rgba(0, 255, 102, 0.65),
                   0 0 14px rgba(0, 255, 102, 0.24) !important;
  }

  html body summary[aria-controls="communities_section"]::marker {
      color: #00ff66 !important;
  }

    /* 23 / Communities: links and items */
  html body #communities_section li,
  html body #communities_section a,
  html body #communities_section span,
  html body #communities_section p,
  html body #communities_section small,
  html body #communities_section strong,
  html body #communities_section button,
  html body #communities_section faceplate-tracker,
  html body #communities_section faceplate-icon,
  html body #communities_section [role="link"],
  html body #communities_section [role="button"],
  html body #left-sidebar faceplate-expandable-section-helper > details li,
  html body #left-sidebar faceplate-expandable-section-helper > details a,
  html body #left-sidebar faceplate-expandable-section-helper > details span,
  html body #left-sidebar faceplate-expandable-section-helper > details p,
  html body #left-sidebar faceplate-expandable-section-helper > details small,
  html body #left-sidebar faceplate-expandable-section-helper > details strong,
  html body #left-sidebar faceplate-expandable-section-helper > details button,
  html body #left-sidebar faceplate-expandable-section-helper > details faceplate-tracker,
  html body #left-sidebar faceplate-expandable-section-helper > details faceplate-icon,
  html body #left-sidebar faceplate-expandable-section-helper > details [role="link"],
  html body #left-sidebar faceplate-expandable-section-helper > details [role="button"],
  html body #left-sidebar a[href^="/r/"],
  html body nav[aria-label="Primary"] a[href^="/r/"] {
      color: #a5ffb7 !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
      letter-spacing: .3px !important;
      text-shadow: 0 0 4px rgba(0, 255, 102, 0.27) !important;
  }

  html body #communities_section a[href],
  html body #left-sidebar a[href^="/r/"],
  html body nav[aria-label="Primary"] a[href^="/r/"] {
      color: #00ff66 !important;
      text-decoration-color: rgba(0, 255, 102, 0.42) !important;
  }

  html body #communities_section a:hover,
  html body #communities_section a:focus,
  html body #left-sidebar a[href^="/r/"]:hover,
  html body nav[aria-label="Primary"] a[href^="/r/"]:hover,
  html body #left-sidebar faceplate-expandable-section-helper a:hover {
      color: #b6ffc5 !important;
      background-color: #0d2a17 !important;
      border-radius: 6px !important;
      text-shadow: 0 0 7px rgba(0, 255, 102, 0.72) !important;
  }

  html body #communities_section a[aria-current="page"],
  html body #left-sidebar a[href^="/r/"][aria-current="page"] {
      color: #00ff66 !important;
      background-color: #12371e !important;
      border-left: 2px solid #00ff66 !important;
  }

  html body #left-sidebar hr,
  html body #left-sidebar [role="separator"],
  html body nav[aria-label="Primary"] hr,
  html body nav[aria-label="Primary"] [role="separator"] {
      border-color: rgba(0, 255, 102, 0.25) !important;
  }

    /* 24 / Communities: heading and component color refinement */
  html body summary[aria-controls="communities_section"],
  html body summary[aria-controls="communities_section"] span,
  html body summary[aria-controls="communities_section"] div,
  html body summary[aria-controls="communities_section"] strong,
  html body summary[aria-controls="communities_section"] small,
  html body summary[aria-controls="communities_section"] faceplate-icon,
  html body summary[aria-controls="communities_section"] rpl-icon {
      color: #00ff66 !important;
      fill: currentColor !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
      text-shadow: 0 0 6px rgba(0, 255, 102, 0.55) !important;
  }

    /* 25 / Communities: shadow host inherited theme tokens */
  html body left-nav-communities-controller,
  html body #left-sidebar faceplate-expandable-section-helper,
  html body #communities_section {
      --color-neutral-content: #a5ffb7 !important;
      --color-neutral-content-weak: #77ba8c !important;
      --color-neutral-content-strong: #00ff66 !important;
      --color-primary: #00ff66 !important;
      --color-primary-onBackground: #00ff66 !important;
      --color-neutral-background: #07180b !important;
      --color-neutral-background-weak: #07180b !important;
      --color-neutral-background-strong: #0c2412 !important;
      --color-neutral-background-hover: #0d2a17 !important;
      --color-neutral-background-selected: #12371e !important;
      --color-secondary-background: #07180b !important;
      --color-secondary-background-hover: #0d2a17 !important;
      --color-secondary-background-selected: #12371e !important;
      --color-button-plain-text: #00ff66 !important;
      --color-button-plain-background-hover: #0d2a17 !important;
      --color-button-secondary-text: #a5ffb7 !important;
      --color-neutral-border: rgba(0, 255, 102, 0.27) !important;
      --color-tone-1: #b6ffc5 !important;
      --color-tone-2: #a5ffb7 !important;
      --color-tone-3: #77ba8c !important;
      background-color: #07180b !important;
      color: #00ff66 !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  }

    /* 26 / Communities: fallback light-DOM labels */
  html body #communities_section a,
  html body #communities_section a:visited,
  html body #communities_section span,
  html body #communities_section p,
  html body #communities_section small,
  html body #communities_section strong,
  html body #communities_section label,
  html body #communities_section button,
  html body #communities_section .left-nav-manage-communities-link,
  html body #communities_section [class*="community-name"],
  html body left-nav-communities-controller {
      color: #00ff66 !important;
      font-family: "Share Tech Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
      text-shadow: 0 0 5px rgba(0, 255, 102, 0.38) !important;
  }

  html body #communities_section a:hover,
  html body #communities_section button:hover,
  html body left-nav-communities-controller:hover {
      color: #b6ffc5 !important;
      background-color: #0d2a17 !important;
  }

  html body #communities_section img {
      filter: none !important;
  }


  /* ================================================================
     V5.3 / FROSTED GREEN GLASS + MATRIX BOKEH + CRT SCANLINES
     Finishing overrides. Wallpaper stored inside CSS; no external assets.
     ================================================================ */

  /* 27 / Embedded cyber matrix bokeh wallpaper + original CRT phosphor scanlines.
     Both images are embedded. No external URLs or separate files needed.
     First background layer: original translucent 8x12px scanlines.
     Second background layer: optimized 1672x941 JPEG (centered, cover). */
  html {
      background-color: #010501 !important;
      background-image: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAgAAAAMCAYAAABfnvydAAAARUlEQVR42mNk+J9izsDAwMSAAP+Q+SwMDAz3CCl4S0jBPyhmQFPEwICmEytgYWBgYCdkxU98JhBlhTIhK14TUvCJIjcAAFbPD5NNB2CVAAAAAElFTkSuQmCC"), url("data:image/jpeg;base64,") !important;
      background-repeat: repeat, no-repeat !important;
      background-position: left top, center center !important;
      background-size: 8px 12px, cover !important;
      background-attachment: fixed, fixed !important;
  }

  /* 28 / Uncover the wallpaper behind main feed and site layout. */
  html body,
  html body shreddit-app,
  html body #main-content,
  html body #main,
  html body main,
  html body #subgrid-container,
  html body #main-content .bg-neutral-background,
  html body #main-content .bg-neutral-background-strong,
  html body .bg-neutral-background,
  html body .bg-neutral-background-strong {
      background-color: transparent !important;
      background-image: none !important;
  }

  /* 29 / Main feed shells: 16% tinted glass, not solid black/green.
     This catches feed layouts where a center-column container obscures
     the CRT pattern behind the individual post cards. */
  html body shreddit-feed,
  html body #main-feed,
  html body #feed-content,
  html body #main-feed-container,
  html body #subreddit-feed,
  html body #main-content shreddit-feed,
  html body #main-content [data-testid="feed-container"],
  html body [data-testid="feed-container"],
  html body .feed-container {
      background-color: rgba(5, 27, 12, 0.16) !important;
      border-color: rgba(0, 255, 102, 0.14) !important;
  }

  /* 30 / Actual post/feed cards and comment containers: frosted green.
     Lower opacity lets scanlines remain plainly visible through cards. */
  html body shreddit-post,
  html body shreddit-feed shreddit-post,
  html body [data-testid="post-container"],
  html body [data-testid="post-card"],
  html body shreddit-feed article,
  html body shreddit-comment,
  html body [data-testid="comment-container"],
  html body .bg-neutral-background-weak,
  html body .bg-secondary-background,
  html body .bg-secondary-background-weak {
      background-color: rgba(8, 42, 19, 0.57) !important;
      background-image: linear-gradient(125deg,
          rgba(48, 143, 67, 0.15),
          rgba(2, 18, 8, 0.03)) !important;
      border-color: rgba(76, 255, 129, 0.39) !important;
      -webkit-backdrop-filter: blur(1px) saturate(135%) !important;
      backdrop-filter: blur(1px) saturate(135%) !important;
  }

  /* 31 / Main feed post text/content wrappers should never repaint
     opaque backgrounds on top of the frosted post card. */
  html body shreddit-post [slot="text-body"],
  html body shreddit-post [data-testid="post-text-container"],
  html body shreddit-post shreddit-post-text-body,
  html body shreddit-feed [data-testid="post-text-container"],
  html body shreddit-post [id$="-post-rtjson-content"],
  html body shreddit-comment [id$="-comment-rtjson-content"] {
      background-color: transparent !important;
  }

  /* 32 / Navigation and Communities: tinted translucent green glass. */
  html body #left-sidebar,
  html body #left-sidebar-container,
  html body #flex-left-nav-container,
  html body #right-sidebar-container,
  html body .left-sidebar-container,
  html body .right-sidebar-container,
  html body [data-testid="left-sidebar"],
  html body [data-testid="right-sidebar"],
  html body reddit-sidebar-nav,
  html body nav[aria-label="Primary"],
  html body aside,
  html body #communities_section,
  html body left-nav-communities-controller,
  html body #left-sidebar faceplate-expandable-section-helper,
  html body #left-sidebar faceplate-expandable-section-helper > details {
      background-color: rgba(7, 39, 16, 0.60) !important;
      background-image: linear-gradient(145deg,
          rgba(49, 132, 65, 0.13),
          rgba(1, 15, 5, 0.02)) !important;
      border-color: rgba(0, 255, 102, 0.30) !important;
      -webkit-backdrop-filter: blur(1px) saturate(125%) !important;
      backdrop-filter: blur(1px) saturate(125%) !important;
  }

  /* 33 / Header moderately denser to protect its icons and search bar. */
  html body shreddit-header,
  html body reddit-header-large {
      background-color: rgba(5, 29, 12, 0.77) !important;
      background-image: linear-gradient(110deg,
          rgba(45, 143, 58, 0.10),
          rgba(0, 8, 3, 0.02)) !important;
      border-color: rgba(0, 255, 102, 0.36) !important;
      -webkit-backdrop-filter: blur(1px) saturate(125%) !important;
      backdrop-filter: blur(1px) saturate(125%) !important;
  }

  /* 34 / Composer and inputs: readable green-tinted glass. */
  html body input[type="text"],
  html body input[type="search"],
  html body input:not([type]),
  html body textarea,
  html body select,
  html body [role="searchbox"],
  html body [role="textbox"],
  html body [contenteditable="true"] {
      background-color: rgba(7, 38, 15, 0.68) !important;
      border-color: rgba(0, 255, 102, 0.42) !important;
      -webkit-backdrop-filter: blur(1px) !important;
      backdrop-filter: blur(1px) !important;
  }

  /* 35 / Popovers remain more opaque than the feed for readability. */
  html body [role="dialog"],
  html body [role="menu"],
  html body [role="listbox"],
  html body [role="tooltip"],
  html body [data-radix-popper-content-wrapper],
  html body faceplate-dialog,
  html body faceplate-dropdown-menu {
      background-color: rgba(8, 37, 16, 0.83) !important;
      border-color: rgba(0, 255, 102, 0.37) !important;
      -webkit-backdrop-filter: blur(1px) !important;
      backdrop-filter: blur(1px) !important;
  }

  /* 36 / Subtle hover / active states still allow the lines through. */
  html body #communities_section a:hover,
  html body #left-sidebar a:hover,
  html body nav[aria-label="Primary"] a:hover,
  html body #left-sidebar faceplate-expandable-section-helper a:hover {
      background-color: rgba(9, 78, 31, 0.53) !important;
  }
  html body #communities_section a[aria-current="page"],
  html body #left-sidebar a[aria-current="page"],
  html body nav[aria-label="Primary"] a[aria-current="page"] {
      background-color: rgba(12, 83, 34, 0.66) !important;
  }

  /* 37 / Inherited Reddit color tokens (including Communities shadow
     components) use alpha colors instead of opaque surfaces. */
  :root,
  html.theme-beta,
  html.theme-rpl,
  html.theme-dark,
  html.theme-light,
  html body,
  html body .theme-beta,
  html body .theme-rpl,
  html body shreddit-app,
  html body shreddit-header {
      --color-neutral-background: rgba(1, 5, 1, 0.05) !important;
      --color-neutral-background-weak: rgba(8, 42, 19, 0.57) !important;
      --color-neutral-background-strong: rgba(9, 37, 17, 0.56) !important;
      --color-neutral-background-hover: rgba(9, 78, 31, 0.53) !important;
      --color-neutral-background-selected: rgba(12, 83, 34, 0.66) !important;
      --color-secondary-background: rgba(8, 42, 19, 0.57) !important;
      --color-secondary-background-hover: rgba(9, 78, 31, 0.53) !important;
      --color-secondary-background-selected: rgba(12, 83, 34, 0.66) !important;
      --color-button-secondary-background: rgba(12, 36, 18, 0.73) !important;
  }

  html body left-nav-communities-controller,
  html body #left-sidebar faceplate-expandable-section-helper,
  html body #communities_section {
      --color-neutral-background: rgba(7, 39, 16, 0.60) !important;
      --color-neutral-background-weak: rgba(7, 39, 16, 0.60) !important;
      --color-neutral-background-strong: rgba(9, 37, 17, 0.56) !important;
      --color-neutral-background-hover: rgba(9, 78, 31, 0.53) !important;
      --color-neutral-background-selected: rgba(12, 83, 34, 0.66) !important;
      --color-secondary-background: rgba(7, 39, 16, 0.60) !important;
      --color-secondary-background-hover: rgba(9, 78, 31, 0.53) !important;
      --color-secondary-background-selected: rgba(12, 83, 34, 0.66) !important;
  }
}
